#include <strstream>
#include <cassert>
#include <type_traits>
#include <utility>
#include <string>
int main() {
    char input[] = "42";
    std::istrstream reader{input};
    assert(reader.str() == input);
    int value{};
    reader >> value;
    assert(value == 42);
    std::ostrstream output;
    output << value << std::ends;
    assert(std::string(output.str()) == "42");
    output.freeze(false);
    char buffer[32]{};
    std::strstream stream{buffer, 32};
    stream << "73";
    stream.seekg(0);
    stream >> value;
    assert(value == 73);
    std::strstreambuf storage{buffer, 32};
    storage.sgetc();
    storage.sbumpc();
    storage.sputbackc(buffer[0]);
}
